def eligible(entries, required_features):
    """Return entries safe for the requested feature set."""
    return [entry for entry in entries if entry.get("enabled", True) and not entry.get("expired", False) and isinstance(entry.get("price"), (int, float)) and not isinstance(entry.get("price"), bool) and entry.get("price") == 0 and all(f in entry.get("features", []) for f in required_features)]
